  .meta dd { margin: .25rem 0 0; font-weight: 600; }

  /* The painting, drawn in CSS: red square top right, blue bottom left,
     yellow rectangle bottom right, thick black divisions on white ground */
  .canvas-mondrian {
    position: relative; aspect-ratio: 1 / 1; width: 100%; max-width: 34rem; margin-inline: auto;
    display: grid; grid-template-columns: 5fr 3fr 2fr; grid-template-rows: 5fr 2fr;
    gap: var(--line); border: var(--line) solid var(--black); background: var(--black);
  }
